from typing import List, Sequence, Tuple

Vector = Tuple[float, ...]
Pattern = Tuple[bool, ...]

def shatters_and_certify(
    W: Sequence[Vector], b: Sequence[float], pts: Sequence[Vector]
) -> bool:
    patterns: List[Pattern] = [
        tuple(sum(w * xj for w, xj in zip(Wi, x)) + bi > 0.0
              for Wi, bi in zip(W, b))
        for x in pts
    ]
    r: int = len(set(patterns))
    shatters: bool = (r == len(pts))
    if shatters:
        assert len(pts) <= 2 ** len(W)
    return shatters

