from itertools import chain, combinations
import matplotlib.pyplot as plt

def main() -> None:
    atoms = ["A", "B", "C"]              # three linear regions
    levels = {}
    for k in range(len(atoms) + 1):
        levels[k] = [frozenset(c) for c in combinations(atoms, k)]
    plt.figure(figsize=(7, 5))
    pos = {}
    for k, nodes in levels.items():
        for j, s in enumerate(nodes):
            x = j - (len(nodes) - 1) / 2
            pos[s] = (x, k)
            label = "{" + ",".join(sorted(s)) + "}" if s else "0"
            plt.scatter([x], [k], s=600, color="#cfe8ff", edgecolor="k", zorder=2)
            plt.text(x, k, label, ha="center", va="center", fontsize=8, zorder=3)
    for s, (x, k) in pos.items():
        for t, (x2, k2) in pos.items():
            if k2 == k + 1 and s < t:
                plt.plot([x, x2], [k, k2], color="gray", lw=0.8, zorder=1)
    plt.title(f"Decision algebra of r=3 regions: 2^3 = 8 elements")
    plt.axis("off"); plt.tight_layout(); plt.savefig("lattice.png", dpi=150)

if __name__ == "__main__":
    main()
